def validSubarraySplit(self, nums):
    from math import gcd
    n = len(nums)
    dp = [float('inf')] * n
    for i in range(n):
        for j in range(i + 1):
            if gcd(nums[j], nums[i]) > 1:
                dp[i] = min(dp[i], (dp[j-1] if j > 0 else 0) + 1)
    return dp[-1] if dp[-1] != float('inf') else -1

def distinctAverages(self, nums):
    nums.sort()
    avgs = set()
    l, r = 0, len(nums) - 1
    while l < r:
        avgs.add(nums[l] + nums[r])
        l += 1
        r -= 1
    return len(avgs)

def countGoodStrings(self, low, high, zero, one):
    MOD = 10**9 + 7
    dp = [0] * (high + 1)
    dp[0] = 1
    res = 0
    for i in range(1, high + 1):
        if i >= zero:
            dp[i] += dp[i - zero]
        if i >= one:
            dp[i] += dp[i - one]
        dp[i] %= MOD
        if i >= low:
            res = (res + dp[i]) % MOD
    return res

def mostProfitablePath(self, edges, bob, amount):
    from collections import defaultdict, deque
    n = len(amount)
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    # Find Bob's path to 0
    parent = [-1] * n
    visited = [False] * n
    visited[bob] = True
    q = deque([bob])
    while q:
        node = q.popleft()
        for nei in g[node]:
            if not visited[nei]:
                visited[nei] = True
                parent[nei] = node
                q.append(nei)
    bob_time = {}
    cur, t = bob, 0
    while cur != -1:
        bob_time[cur] = t
        cur = parent[cur] if cur != 0 else -1
        t += 1
    # DFS for Alice
    res = float('-inf')
    stack = [(0, -1, 0, 0)]  # node, parent, time, income
    while stack:
        node, par, time, income = stack.pop()
        if node in bob_time:
            if time < bob_time[node]:
                income += amount[node]
            elif time == bob_time[node]:
                income += amount[node] // 2
        else:
            income += amount[node]
        children = [nei for nei in g[node] if nei != par]
        if not children:
            res = max(res, income)
        for nei in children:
            stack.append((nei, node, time + 1, income))
    return res

def splitMessage(self, message, limit):
    def digits(x):
        return len(str(x))
    n = len(message)
    for k in range(1, n + 1):
        dk = digits(k)
        overhead = sum(digits(i) + dk + 3 for i in range(1, k + 1))
        if overhead + n <= k * limit:
            # Build result
            res = []
            idx = 0
            for i in range(1, k + 1):
                suffix = f'<{i}/{k}>'
                take = limit - len(suffix)
                res.append(message[idx:idx+take] + suffix)
                idx += take
            return res
    return []

def subarrayLCM(self, nums, k):
    from math import gcd
    n = len(nums)
    res = 0
    for i in range(n):
        cur_lcm = 1
        for j in range(i, n):
            cur_lcm = cur_lcm * nums[j] // gcd(cur_lcm, nums[j])
            if cur_lcm == k:
                res += 1
            elif cur_lcm > k:
                break
    return res

def minimumOperations(self, root):
    from collections import deque
    def min_swaps(arr):
        idx = sorted(range(len(arr)), key=lambda i: arr[i])
        visited = [False] * len(arr)
        swaps = 0
        for i in range(len(arr)):
            if visited[i] or idx[i] == i:
                continue
            cycle = 0
            j = i
            while not visited[j]:
                visited[j] = True
                j = idx[j]
                cycle += 1
            swaps += cycle - 1
        return swaps
    q = deque([root])
    res = 0
    while q:
        level = []
        for _ in range(len(q)):
            node = q.popleft()
            level.append(node.val)
            if node.left: q.append(node.left)
            if node.right: q.append(node.right)
        res += min_swaps(level)
    return res

def maxPalindromes(self, s, k):
    n = len(s)
    # is_pal[i][j] = True if s[i..j] is palindrome
    is_pal = [[False]*n for _ in range(n)]
    for i in range(n-1, -1, -1):
        for j in range(i, n):
            if s[i] == s[j] and (j - i < 2 or is_pal[i+1][j-1]):
                is_pal[i][j] = True
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = dp[i-1]
        for j in range(i - k + 1):
            if is_pal[j][i-1]:
                dp[i] = max(dp[i], dp[j] + 1)
                break  # greedy: take shortest valid palindrome ending here
    return dp[n]

def minimumFuelCost(self, roads, seats):
    from collections import defaultdict
    import math
    g = defaultdict(list)
    for u, v in roads:
        g[u].append(v)
        g[v].append(u)
    self.fuel = 0
    def dfs(node, parent):
        people = 1
        for nei in g[node]:
            if nei != parent:
                people += dfs(nei, node)
        if node != 0:
            self.fuel += math.ceil(people / seats)
        return people
    dfs(0, -1)
    return self.fuel

def maxXor(self, n, edges, values):
