                stack.append((nei, node))
    for node in reversed(order):
        sub_xor[node] = values[node]
        for nei in g[node]:
            if nei != parent[node]:
                sub_xor[node] ^= sub_xor[nei]
    # Use trie to find max XOR among non-ancestor pairs
    # Simplified: check all pairs (exponential), use trie on all subtree xors
    trie = {}
    res = 0
    def insert(val):
        node = trie
        for i in range(46, -1, -1):
            bit = (val >> i) & 1
            if bit not in node:
                node[bit] = {}
            node = node[bit]
    def query(val):
        node = trie
        r = 0
        for i in range(46, -1, -1):
            bit = (val >> i) & 1
            want = 1 - bit
            if want in node:
                r |= (1 << i)
                node = node[want]
            elif bit in node:
                node = node[bit]
            else:
                break
        return r
    for node in order:
        if trie:
            res = max(res, query(sub_xor[node]))
        insert(sub_xor[node])
    return res

