def countPalindromes(self, s):
    MOD = 10**9 + 7
    n = len(s)
    # prefix[i][d1][d2] = count of subsequences (d1, d2) in s[0..i-1]
    # suffix[i][d1][d2] = count of subsequences (d1, d2) in s[i+1..n-1]
    pre = [[[0]*10 for _ in range(10)] for _ in range(n)]
    suf = [[[0]*10 for _ in range(10)] for _ in range(n)]
    cnt = [0] * 10
    for i in range(n):
        d = int(s[i])
        for d1 in range(10):
            for d2 in range(10):
                pre[i][d1][d2] = (pre[i-1][d1][d2] if i > 0 else 0)
            pre[i][d1][d] += cnt[d1] if i > 0 else 0
        cnt[d] += 1
    cnt = [0] * 10
    for i in range(n-1, -1, -1):
        d = int(s[i])
        for d1 in range(10):
            for d2 in range(10):
                suf[i][d1][d2] = suf[i+1][d1][d2] if i < n-1 else 0
            suf[i][d1][d] += cnt[d1] if i < n-1 else 0
        cnt[d] += 1
    res = 0
    for i in range(2, n-2):
        for d1 in range(10):
            for d2 in range(10):
                res = (res + pre[i-1][d1][d2] * suf[i+1][d2][d1]) % MOD
    return res

