def magnificentSets(self, n, edges):
    from collections import defaultdict, deque
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    color = [0] * (n + 1)
    components = []
    def get_component(start):
        comp = []
        q = deque([start])
        color[start] = 1
        while q:
            node = q.popleft()
            comp.append(node)
            for nei in g[node]:
                if color[nei] == 0:
                    color[nei] = -color[node]
                    q.append(nei)
                elif color[nei] == color[node]:
                    return None
        return comp
    for i in range(1, n + 1):
        if color[i] == 0:
            comp = get_component(i)
            if comp is None:
                return -1
            components.append(comp)
    def max_groups(comp):
        best = 0
        for start in comp:
            visited = {start: 1}
            q = deque([start])
            mx = 1
            while q:
                node = q.popleft()
                for nei in g[node]:
                    if nei not in visited:
                        visited[nei] = visited[node] + 1
                        mx = max(mx, visited[nei])
                        q.append(nei)
            best = max(best, mx)
        return best
    return sum(max_groups(comp) for comp in components)

def evenProduct(self, nums):
