class Allocator:
    def __init__(self, n):
        self.mem = [0] * n
        self.n = n
    def allocate(self, size, mID):
        count = 0
        for i in range(self.n):
            if self.mem[i] == 0:
                count += 1
                if count == size:
                    for j in range(i - size + 1, i + 1):
                        self.mem[j] = mID
                    return i - size + 1
            else:
                count = 0
        return -1
    def freeMemory(self, mID):
        count = 0
        for i in range(self.n):
            if self.mem[i] == mID:
                self.mem[i] = 0
                count += 1
        return count

def similarPairs(self, words):
    from collections import Counter
    masks = []
    for w in words:
        mask = 0
        for c in w:
            mask |= (1 << (ord(c) - ord('a')))
        masks.append(mask)
    cnt = Counter(masks)
    return sum(v * (v-1) // 2 for v in cnt.values())

def smallestValue(self, n):
