        s = 0
        temp = n
        d = 2
        while d * d <= temp:
            while temp % d == 0:
                s += d
                temp //= d
            d += 1
        if temp > 1:
            s += temp
        if s == n:
            return n
        n = s

def isPossible(self, n, edges):
    from collections import defaultdict
    g = defaultdict(set)
    for u, v in edges:
        g[u].add(v)
        g[v].add(u)
    odd = [node for node in range(1, n+1) if len(g[node]) % 2 == 1]
    if len(odd) == 0:
        return True
    if len(odd) == 2:
        a, b = odd
        if b not in g[a]:
            return True
        for c in range(1, n+1):
            if c != a and c != b and a not in g[c] and b not in g[c]:
                return True
        return False
    if len(odd) == 4:
        a, b, c, d = odd
        # Try all 3 pairings
        if b not in g[a] and d not in g[c]:
            return True
        if c not in g[a] and d not in g[b]:
            return True
        if d not in g[a] and c not in g[b]:
            return True
        return False
    return False

