def isThereAPath(self, grid):
    m, n = len(grid), len(grid[0])
    if (m + n - 1) % 2 == 1:
        return False
    # Transform 0 -> -1
    dp = [[set() for _ in range(n)] for _ in range(m)]
    dp[0][0].add(1 if grid[0][0] else -1)
    for i in range(m):
        for j in range(n):
            val = 1 if grid[i][j] else -1
            if i == 0 and j == 0:
                continue
            prev = set()
            if i > 0:
                prev |= dp[i-1][j]
            if j > 0:
                prev |= dp[i][j-1]
            dp[i][j] = {s + val for s in prev}
    return 0 in dp[m-1][n-1]

def captureForts(self, forts):
    res = 0
    prev = -1
    for i, f in enumerate(forts):
        if f != 0:
            if prev >= 0 and forts[prev] != f:
                res = max(res, i - prev - 1)
            prev = i
    return res

def topStudents(self, positive_feedback, negative_feedback, report, student_id, k):
    pos = set(positive_feedback)
    neg = set(negative_feedback)
    scores = []
    for i, r in enumerate(report):
        score = 0
        for word in r.split():
            if word in pos:
                score += 3
            elif word in neg:
                score -= 1
        scores.append((-score, student_id[i]))
    scores.sort()
    return [sid for _, sid in scores[:k]]

def closetTarget(self, words, target, startIndex):
    n = len(words)
    res = float('inf')
    for i in range(n):
        if words[i] == target:
            dist = min(abs(i - startIndex), n - abs(i - startIndex))
            res = min(res, dist)
    return res if res != float('inf') else -1

def maximumTastiness(self, price, k):
    price.sort()
    def can(mid):
        count = 1
        prev = price[0]
        for i in range(1, len(price)):
            if price[i] - prev >= mid:
                count += 1
                prev = price[i]
        return count >= k
    lo, hi = 0, price[-1] - price[0]
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

def countPartitions(self, nums, k):
    MOD = 10**9 + 7
    if sum(nums) < 2 * k:
        return 0
    # Count subsets with sum < k
    dp = [0] * k
    dp[0] = 1
    for x in nums:
        for j in range(k-1, x-1, -1):
            dp[j] = (dp[j] + dp[j-x]) % MOD
    bad = sum(dp) * 2 % MOD
    total = pow(2, len(nums), MOD)
    return (total - bad) % MOD
